// Generated by `xark client` from `schema.json`: a typed client for the `merkle` circuit.
//
//   #[circuit]
//   fn merkle(leaf: Private<Field>, siblings: Private<[Field; 4]>, index_bits: Private<[Field; 4]>, root: Public<Field>)
//
// `xark build` records the circuit's parameter types in target/xark/merkle/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); xark-wasm encodes them against the
// schema, exactly as `xark prove --inputs` does.

/** A field element: a `bigint`, a safe integer, or a decimal / `0x`-hex string. */
export type FieldLike = bigint | number | string;
/** Bytes: a `Uint8Array`, byte values, or a `0x`-hex string. */
export type Bytes = Uint8Array | readonly number[] | string;

/** Every input of `merkle`. */
export interface MerkleInputs {
  leaf: FieldLike;
  /** Exactly 4 elements. */
  siblings: readonly FieldLike[];
  /** Exactly 4 elements. */
  indexBits: readonly FieldLike[];
  root: FieldLike;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface MerklePublicInputs {
  root: FieldLike;
}

/** The public inputs, decoded from a proof. */
export interface MerklePublicValues {
  root: bigint;
}

/** The parts of `@blueshift-gg/xark-wasm` this client uses (any of its builds). */
export interface XarkWasm {
  prove(circuit: Uint8Array, provingKey: Uint8Array, inputs: Record<string, string>, sources?: string): { proof: Uint8Array; publicInputs: Uint8Array };
  verify(verifyingKey: Uint8Array, proof: Uint8Array, publicInputs: Uint8Array): boolean;
  encodeInputs(schema: string, inputs: string): Record<string, string>;
  encodePublicInputs(schema: string, publicInputs: string): Uint8Array;
  decodePublicValues(schema: string, publicInputs: Uint8Array): string;
  valueFields(schema: string, typeName: string, value: string): string[];
}

/** A proof, with its public inputs decoded and as the bytes `verify` takes. */
export interface MerkleProof {
  proof: Uint8Array;
  publicInputs: MerklePublicValues;
  publicInputBytes: Uint8Array;
}

/**
 * The build output a `Merkle` works from (`target/xark/merkle/`): `circuit`
 * (circuit.xbc) and `provingKey` (pk.bin) to prove, `verifyingKey` (vk.bin) to
 * verify, and `sources` (sources.json, as text) so that inputs failing a check
 * name its source line.
 */
export interface MerkleKeys {
  circuit?: Uint8Array;
  provingKey?: Uint8Array;
  verifyingKey?: Uint8Array;
  sources?: string;
}

/** Each part of `MerkleKeys` as `xark build` and `xark setup` name its file. */
const FILES = {
  circuit: "circuit.xbc",
  provingKey: "pk.bin",
  verifyingKey: "vk.bin",
  sources: "sources.json",
} as const;

/**
 * Prove and verify `merkle` with the xark-wasm module you pass in:
 *
 * ```ts
 * import * as wasm from "@blueshift-gg/xark-wasm"; // node, web (after `await init()`), or bundler
 * const circuit = new Merkle(wasm, { circuit: xbc, provingKey: pk, verifyingKey: vk, sources });
 * const { proof, publicInputs } = circuit.prove(inputs);
 * circuit.verify(proof, publicInputs); // true
 * ```
 */
export class Merkle {
  /** The circuit's `schema.json`. */
  static readonly schema = "{\"circuit\":\"merkle\",\"inputs\":[{\"name\":\"leaf\",\"type\":\"field\",\"visibility\":\"private\"},{\"name\":\"siblings\",\"type\":{\"array\":{\"len\":4,\"of\":\"field\"}},\"visibility\":\"private\"},{\"name\":\"index_bits\",\"type\":{\"array\":{\"len\":4,\"of\":\"field\"}},\"visibility\":\"private\"},{\"name\":\"root\",\"type\":\"field\",\"visibility\":\"public\"}],\"public_inputs\":[\"root\"],\"types\":{},\"version\":2}";

  constructor(
    private readonly wasm: XarkWasm,
    private readonly keys: MerkleKeys,
  ) {}

  /**
   * Fetch the build output from `base`, a URL serving a copy of
   * `target/xark/merkle/` (relative to the page in a browser):
   * `await Merkle.load(wasm, "/circuits/merkle/")`. `only` fetches less
   * (`["verifyingKey"]` for a verifier); a missing `sources.json` is skipped.
   */
  static async load(
    wasm: XarkWasm,
    base: string | URL,
    only: readonly (keyof MerkleKeys)[] = ["circuit", "provingKey", "verifyingKey", "sources"],
    init?: RequestInit,
  ): Promise<Merkle> {
    const root = new URL(base, (globalThis as { location?: { href: string } }).location?.href);
    if (!root.pathname.endsWith("/")) root.pathname += "/";
    const keys: Record<string, Uint8Array | string> = {};
    await Promise.all(
      only.map(async (part) => {
        const url = new URL(FILES[part], root);
        const res = await fetch(url, init);
        if (!res.ok) {
          if (part === "sources" && res.status === 404) return;
          throw new Error(`fetching ${url}: ${res.status} ${res.statusText}`);
        }
        keys[part] = part === "sources" ? await res.text() : new Uint8Array(await res.arrayBuffer());
      }),
    );
    return new Merkle(wasm, keys as MerkleKeys);
  }

  /**
   * Prove `inputs`. Throws if one is malformed (naming it), or if they fail a
   * check (naming its source line when `sources` was given).
   */
  prove(inputs: MerkleInputs): MerkleProof {
    const { circuit, provingKey, sources } = this.keys;
    if (!circuit || !provingKey) throw new Error("proving needs `circuit` (circuit.xbc) and `provingKey` (pk.bin)");
    const leaves = this.wasm.encodeInputs(Merkle.schema, toJson(inputs));
    const { proof, publicInputs } = this.wasm.prove(circuit, provingKey, leaves, sources);
    return { proof: proof.slice(), publicInputs: this.decodePublicInputs(publicInputs), publicInputBytes: publicInputs.slice() };
  }

  /** Whether `proof` proves these public inputs. */
  verify(proof: Uint8Array, publicInputs: MerklePublicInputs | MerklePublicValues | Uint8Array): boolean {
    const { verifyingKey } = this.keys;
    if (!verifyingKey) throw new Error("verifying needs `verifyingKey` (vk.bin)");
    const bytes = publicInputs instanceof Uint8Array ? publicInputs : this.encodePublicInputs(publicInputs);
    try {
      return this.wasm.verify(verifyingKey, proof, bytes);
    } catch {
      return false; // malformed proof bytes
    }
  }

  /** The public inputs as the canonical bytes (`public_inputs.bin`). */
  encodePublicInputs(publicInputs: MerklePublicInputs | MerklePublicValues): Uint8Array {
    return this.wasm.encodePublicInputs(Merkle.schema, toJson(publicInputs));
  }

  /** Canonical public-input bytes, decoded. */
  decodePublicInputs(bytes: Uint8Array): MerklePublicValues {
    return decodePublic(JSON.parse(this.wasm.decodePublicValues(Merkle.schema, bytes)));
  }
}

function decodePublic(v: any): MerklePublicValues {
  return {
    root: BigInt(v.root),
  };
}

/** JSON for xark-wasm: `bigint`s as decimal, a `Date` as its UTC day (`YYYY-MM-DD`), bytes as hex. */
function toJson(value: unknown): string {
  return JSON.stringify(value, function (this: any, key: string, v: unknown) {
    const raw = this[key];
    if (raw instanceof Date) {
      if (Number.isNaN(raw.getTime())) throw new TypeError(`${key}: invalid Date`);
      return raw.toISOString().slice(0, 10);
    }
    if (typeof raw === "bigint") return raw.toString();
    if (raw instanceof Uint8Array) return "0x" + Array.from(raw, (b) => b.toString(16).padStart(2, "0")).join("");
    if (raw instanceof Set) return [...raw];
    return v;
  });
}

function fromHex(s: string): Uint8Array {
  const h = s.slice(2);
  return Uint8Array.from({ length: h.length / 2 }, (_, i) => parseInt(h.slice(2 * i, 2 * i + 2), 16));
}
